package io.rift.cronos;
import java.nio.file.*;import java.io.*;import java.util.*;
public class StagingCleanupHarness {
 public static void main(String[] args)throws Exception{Path temp=Files.createTempDirectory("rift-staging-test-");try{Path cache=Files.createDirectory(temp.resolve("cache")),old=Files.createDirectories(cache.resolve("imports/12345678-1234-1234-1234-123456789abc/batch"));Files.writeString(old.resolve("art.json"),"{}");Path exported=Files.writeString(cache.resolve("rift-export-123456.tmp"),"data"),unrelated=Files.writeString(cache.resolve("do-not-remove.txt"),"keep");List<File> captured=StagingCleanup.snapshot(cache.toFile());if(captured.size()!=2)throw new AssertionError();Path live=Files.createDirectories(cache.resolve("imports/87654321-1234-1234-1234-123456789abc/live"));Files.writeString(live.resolve("live.json"),"{}");Path outside=Files.writeString(temp.resolve("outside.txt"),"keep");captured.add(outside.toFile());StagingCleanup.remove(cache.toFile(),captured);if(Files.exists(old)||Files.exists(exported)||!Files.exists(unrelated)||!Files.exists(live.resolve("live.json"))||!Files.exists(outside))throw new AssertionError();System.out.println("Staging cleanup snapshot/isolation checks passed");}finally{try(var paths=Files.walk(temp)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception ignored){}});}}}
}
